def recon_all_outputs(params: ReconAll, execution: Execution) -> ReconAllOutputs:
    """Build the ReconAllOutputs object for this tool."""
    root_v: OutputPathType = execution.output_file(".")
    logfile_v: OutputPathType = execution.output_file(f'{params["subjid"]}/scripts/recon-all.log')
    statusfile_v: OutputPathType = execution.output_file(f'{params["subjid"]}/scripts/recon-all-status.log')
    return ReconAllOutputs(
        root=root_v,
        logfile=logfile_v,
        statusfile=statusfile_v,
    )

def recon_all_execute(params: ReconAll, runner: Runner | None = None) -> ReconAllOutputs:
    """
    recon-all

    Performs all, or any part of, the FreeSurfer cortical reconstruction process

    Author: FreeSurfer Developers

    URL: https://github.com/freesurfer/freesurfer

    Args:
        params: The parameters.
        runner: Command runner (defaults to global runner).

    Returns:
        Tool outputs (paths to files produced by the tool).
    """
    recon_all_validate(params)
    runner = runner if runner is not None else get_global_runner()
    execution = runner.start_execution(RECON_ALL_METADATA)
    execution.params(params)
    args = recon_all_cargs(params, execution)
    out = recon_all_outputs(params, execution)
    execution.run(args)
    return out

